<script setup>
import { computed, ref, watch } from 'vue'
const props = defineProps({ characters: { type: Array, default: () => [] }, selectedCharacterId: { type: String, default: '' }, memories: { type: Object, default: () => ({}) } })
const emit = defineEmits(['select-character', 'update:memories', 'close'])
const categories = ['全部', '用户习惯', '重要记忆', '对话碎片', '朋友圈记忆']
const category = ref('全部')
const editTarget = ref(null)
const editingOpen = ref(false)
const confirmAction = ref('')
const draft = ref({ category: '重要记忆', content: '' })
const touchStart = ref(null)
const revealedId = ref('')
const currentCharacter = computed(() => props.characters.find((item) => item.id === props.selectedCharacterId))
const list = computed(() => props.memories[props.selectedCharacterId] || [])
const filtered = computed(() => category.value === '全部' ? list.value : list.value.filter((item) => item.category === category.value))
watch(() => props.selectedCharacterId, () => { category.value = '全部'; revealedId.value = '' })
function updateList(items) { emit('update:memories', { ...props.memories, [props.selectedCharacterId]: items }) }
function beginEdit(item = null) { editTarget.value = item?.id || null; draft.value = { category: item?.category || '重要记忆', content: item?.content || '' }; editingOpen.value = true }
function closeEdit() { editingOpen.value = false; editTarget.value = null; draft.value = { category: '重要记忆', content: '' } }
function saveEdit() { const content = draft.value.content.trim(); if (!content) return; const items = [...list.value]; if (editTarget.value) { const index = items.findIndex((item) => item.id === editTarget.value); if (index >= 0) items[index] = { ...items[index], ...draft.value, content, updatedAt: Date.now() } } else items.unshift({ id: `memory-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, ...draft.value, content, createdAt: Date.now(), sourceThrough: 0 }); updateList(items); closeEdit() }
function confirmDelete(item) { confirmAction.value = item.id }
function deleteMemory() { updateList(list.value.filter((item) => item.id !== confirmAction.value)); confirmAction.value = '' }
function clearAll() { updateList([]); confirmAction.value = '' }
function startSwipe(event, id) { touchStart.value = { x: event.changedTouches[0].clientX, y: event.changedTouches[0].clientY, id } }
function endSwipe(event) { if (!touchStart.value) return; const dx = event.changedTouches[0].clientX - touchStart.value.x; const dy = event.changedTouches[0].clientY - touchStart.value.y; if (Math.abs(dx) > 45 && Math.abs(dx) > Math.abs(dy)) revealedId.value = dx < 0 ? touchStart.value.id : ''; touchStart.value = null }
</script>

<template>
  <div class="memory-overlay">
    <section class="memory-page" role="dialog" aria-modal="true" aria-label="角色长期记忆">
      <header class="memory-header"><button type="button" aria-label="返回聊天配置" @click="emit('close')">‹</button><div><h1>长期记忆</h1><small>{{ currentCharacter?.name || '选择一个角色' }}</small></div><button class="header-clear" type="button" :disabled="!list.length" @click="confirmAction = 'all'">清空</button></header>
      <main class="memory-scroll">
        <div class="memory-character-label">记忆归属角色</div>
        <div class="character-selector"><button v-for="character in characters" :key="character.id" type="button" :class="{ active: character.id === selectedCharacterId }" @click="emit('select-character', character.id)"><span class="character-avatar" :style="character.avatar ? { backgroundImage: `url(${character.avatar})` } : {}">{{ character.avatar ? '' : (character.name || '角').slice(0, 1) }}</span><span>{{ character.name || '未命名角色' }}</span></button><p v-if="!characters.length" class="empty-hint">添加角色后，聊天中整理的记忆会显示在这里。</p></div>
        <div class="memory-summary"><span class="summary-mark">✦</span><div><strong>让重要的内容留在对话里</strong><p>模型会在聊天过程中，间隔整理值得记住的偏好、重要经历与对话片段。记忆仅归属于当前角色。</p></div></div>
        <div class="memory-list-heading"><div><strong>记忆记录</strong><small>{{ list.length }} 条</small></div><button type="button" :disabled="!selectedCharacterId" @click="beginEdit()">＋ 添加记忆</button></div>
        <nav class="memory-categories" aria-label="记忆分类"><button v-for="item in categories" :key="item" type="button" :class="{ active: category === item }" @click="category = item">{{ item }}</button></nav>
        <div v-if="!filtered.length" class="memory-empty"><span>✧</span><strong>这里还没有记忆</strong><p>{{ list.length ? '这个分类暂时没有记录。' : '随着你们的聊天，值得留存的内容会整理在这里。' }}</p></div>
        <article v-for="item in filtered" :key="item.id" class="memory-row-wrap" @touchstart.passive="startSwipe($event, item.id)" @touchend.passive="endSwipe($event)">
          <div class="memory-actions" :class="{ revealed: revealedId === item.id }"><button type="button" @click="beginEdit(item); revealedId = ''">编辑</button><button type="button" @click="confirmDelete(item); revealedId = ''">删除</button></div>
          <div class="memory-row" :class="{ shifted: revealedId === item.id }"><div class="memory-row-meta"><span>{{ item.category }}</span><time>{{ new Date(item.updatedAt || item.createdAt || Date.now()).toLocaleDateString('zh-CN') }}</time><button type="button" class="row-more" :aria-label="`管理${item.category}记忆`" @click="revealedId = revealedId === item.id ? '' : item.id">···</button></div><p>{{ item.content }}</p><small v-if="item.sourceThrough">由聊天内容整理</small></div>
        </article>
      </main>
      <div v-if="editingOpen" class="memory-modal-backdrop" @click.self="closeEdit"><section class="memory-modal" role="dialog" aria-modal="true" aria-label="编辑记忆"><h2>{{ editTarget ? '编辑记忆' : '添加记忆' }}</h2><label>记忆分类<select v-model="draft.category"><option v-for="item in categories.slice(1)" :key="item">{{ item }}</option></select></label><label>记忆内容<textarea v-model="draft.content" maxlength="500" rows="6" placeholder="记录对未来对话有帮助的内容…" /></label><footer><button type="button" @click="closeEdit">取消</button><button type="button" :disabled="!draft.content.trim()" @click="saveEdit">保存</button></footer></section></div>
      <div v-if="confirmAction" class="memory-modal-backdrop" @click.self="confirmAction = ''"><section class="memory-modal confirm-modal" role="alertdialog" aria-modal="true"><span>!</span><h2>{{ confirmAction === 'all' ? '清空该角色的全部记忆？' : '删除这条记忆？' }}</h2><p>{{ confirmAction === 'all' ? `将永久清除「${currentCharacter?.name || '当前角色'}」的全部长期记忆，聊天记录不会受影响。` : '删除后无法恢复。' }}</p><footer><button type="button" @click="confirmAction = ''">取消</button><button type="button" class="danger" @click="confirmAction === 'all' ? clearAll() : deleteMemory()">确认删除</button></footer></section></div>
    </section>
  </div>
</template>

<style scoped>
.memory-overlay{position:fixed;inset:0;z-index:44;background:#f4f4f2}.memory-page{height:100%;display:flex;flex-direction:column;overflow:hidden;color:#454642;background:#f4f4f2}.memory-header{position:absolute;z-index:2;inset:0 0 auto;height:calc(64px + env(safe-area-inset-top));display:grid;grid-template-columns:48px 1fr 54px;align-items:center;padding:env(safe-area-inset-top) 18px 0;background:rgba(255,255,255,.35);border-bottom:1px solid rgba(220,222,218,.35);backdrop-filter:blur(22px) saturate(1.25);-webkit-backdrop-filter:blur(22px) saturate(1.25)}.memory-header>button{height:42px;border:0;color:#5a5b58;background:transparent;font:inherit;font-size:28px}.memory-header h1{margin:0;text-align:center;font-size:16px;font-weight:600}.memory-header small{display:block;margin-top:3px;color:#969792;text-align:center;font-size:10px}.memory-header .header-clear{justify-self:end;font-size:12px;color:#a66d68}.memory-header .header-clear:disabled{color:#bcbdb8}.memory-scroll{width:min(100%,620px);min-height:0;flex:1;overflow:auto;margin:0 auto;padding:calc(64px + env(safe-area-inset-top) + 20px) 20px calc(env(safe-area-inset-bottom) + 24px)}.memory-character-label{margin:0 2px 10px;color:#999a95;font-size:11px}.character-selector{display:flex;gap:10px;overflow:auto;padding:2px 1px 12px}.character-selector button{min-width:68px;display:flex;flex-direction:column;align-items:center;gap:6px;padding:7px 8px;border:1px solid transparent;border-radius:15px;color:#777872;background:transparent;font:inherit;font-size:10px}.character-selector button.active{border-color:#e6e7e1;background:#fff}.character-avatar{width:40px;height:40px;display:grid;place-items:center;border-radius:50%;color:#777;background-color:#e5e5df;background-position:center;background-size:cover;font-size:15px}.empty-hint{color:#999;font-size:11px}.memory-summary{display:flex;gap:12px;margin:11px 0 24px;padding:16px;border:1px solid #ebece8;border-radius:18px;background:#fff}.summary-mark{color:#8ca68f;font-size:20px}.memory-summary strong{font-size:12px;font-weight:600}.memory-summary p{margin:6px 0 0;color:#8d8e89;font-size:10px;line-height:1.7}.memory-list-heading{display:flex;align-items:center;justify-content:space-between;margin:0 2px 12px}.memory-list-heading>div{display:flex;align-items:baseline;gap:8px}.memory-list-heading strong{font-size:14px}.memory-list-heading small{color:#a1a29c;font-size:10px}.memory-list-heading button{padding:8px 12px;border:0;border-radius:18px;color:#637c67;background:#e8eee7;font:inherit;font-size:11px}.memory-list-heading button:disabled{opacity:.5}.memory-categories{display:flex;gap:7px;overflow:auto;margin-bottom:12px}.memory-categories button{flex:none;padding:7px 12px;border:0;border-radius:16px;color:#858680;background:#eaeae7;font:inherit;font-size:10px}.memory-categories button.active{color:#fff;background:#899d8a}.memory-row-wrap{position:relative;overflow:hidden;margin:0 0 9px;border-radius:16px}.memory-actions{position:absolute;inset:0 0 0 auto;display:flex;align-items:stretch}.memory-actions button{width:62px;border:0;color:#fff;background:#839984;font:inherit;font-size:11px}.memory-actions button+button{background:#c7847d}.memory-row{position:relative;min-height:80px;padding:12px 14px;border:1px solid #ebebe7;border-radius:16px;background:#fff;transition:transform .2s}.memory-row.shifted{transform:translateX(-124px)}.memory-row-meta{display:flex;align-items:center;gap:9px;color:#899b8c;font-size:9px}.memory-row-meta time{color:#aaa;font-size:9px}.memory-row .row-more{margin-left:auto;padding:0 4px;border:0;color:#999;background:transparent;font-size:18px}.memory-row p{margin:5px 0 4px;color:#555650;font-size:12px;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}.memory-row>small{color:#b0b0aa;font-size:9px}.memory-empty{padding:48px 12px;text-align:center;color:#a0a19a}.memory-empty>span{font-size:28px}.memory-empty strong{display:block;margin-top:12px;color:#777871;font-size:12px}.memory-empty p{font-size:10px;line-height:1.7}.memory-modal-backdrop{position:fixed;z-index:5;inset:0;display:grid;place-items:center;padding:20px;background:#34363035;backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}.memory-modal{width:min(100%,420px);display:flex;flex-direction:column;gap:14px;padding:21px;border:1px solid #ffffffc9;border-radius:23px;background:#fff;box-shadow:0 18px 55px #33333320}.memory-modal h2{margin:0;color:#555650;font-size:16px;font-weight:600}.memory-modal label{display:flex;flex-direction:column;gap:7px;color:#888982;font-size:10px}.memory-modal select,.memory-modal textarea{width:100%;box-sizing:border-box;padding:11px;border:1px solid #eeefeb;border-radius:12px;outline:0;color:#555650;background:#f8f8f6;font:inherit;font-size:12px}.memory-modal textarea{resize:vertical;line-height:1.7}.memory-modal footer{display:flex;justify-content:flex-end;gap:9px;margin-top:3px}.memory-modal footer button{min-width:75px;padding:10px 13px;border:0;border-radius:14px;color:#777;background:#f0f0ed;font:inherit;font-size:11px}.memory-modal footer button:last-child{color:#fff;background:#859b87}.memory-modal footer button:disabled{opacity:.45}.confirm-modal{text-align:center;align-items:center;gap:10px}.confirm-modal>span{width:32px;height:32px;display:grid;place-items:center;border-radius:50%;color:#a56f69;background:#fbefed;font-weight:700}.confirm-modal p{margin:0;color:#92938d;font-size:11px;line-height:1.7}.confirm-modal footer{width:100%;justify-content:center}.confirm-modal footer .danger{color:#fff;background:#bf7a73}@media(max-width:400px){.memory-scroll{padding-right:15px;padding-left:15px}}
</style>
